FORMER_TAX_MODES = {
    "line_round": ("各行四捨五入", "round"),
    "line_floor": ("各行切捨", "floor"),
}
#: 向きの値 → 名前 (記録の字)
ROUNDING_LABELS = {"round": "四捨五入", "ceil": "切上", "floor": "切捨"}


def move_to_total(apps, schema_editor):
    """消費税の端数の向きが空の取引先に向きを入れる。移した行ごとに記録の 1 行を出す。もう一度呼んでも何も変えない。"""
    Company = apps.get_model("core", "Company")
    Partner = apps.get_model("masters", "Partner")
    logger = logging.getLogger("seizou.settings")
    company = Company.objects.order_by("pk").first()
    company_rounding = company.rounding if company is not None else "round"
    for partner in Partner.objects.filter(tax_rounding="").order_by("pk"):
        if partner.tax_mode in FORMER_TAX_MODES:
            former, rounding = FORMER_TAX_MODES[partner.tax_mode]
            partner.tax_mode = "total"
            partner.tax_rounding = rounding
            partner.save(update_fields=["tax_mode", "tax_rounding"])
            message = (
                f"取引先の消費税の端数の扱いを {former} からトータルに移し、消費税の端数の向きを {ROUNDING_LABELS[rounding]} にした"
                f" (インボイス制度。masters の migration): {partner.code} {partner.name}"
            )
        else:
            rounding = partner.rounding or company_rounding
            partner.tax_rounding = rounding
            partner.save(update_fields=["tax_rounding"])
            message = (
                f"取引先の消費税の端数の向きを {ROUNDING_LABELS.get(rounding, rounding)} にした"
                f" (前は消費税を金額の端数の向きで丸めていたので、同じ向きを写した。masters の migration): {partner.code} {partner.name}"
            )
        logger.info(message)
        print(message)


